      source: 'Kotler & Keller《Marketing Management》；AMA 2017 定義',
      brief: `行銷是**辨識並滿足顧客需求，並從中獲利**的過程。Kotler 講得最精練的一句是「行銷是有利可圖地滿足需求」。

核心是一條鏈：**需要 → 欲望 → 需求 → 產品 → 價值 → 交換 → 市場**。人有需要（口渴），文化與個性把它塑造成欲望（想喝珍奶），有購買力才成為需求。行銷不創造需要，它把需要導向特定的滿足方案。

最重要的一句話：**行銷的目的是讓推銷變得多餘**（Drucker）。如果產品真的貼合顧客，它自己會賣。`,
      advanced: `**AMA 2017 定義**：行銷是創造、溝通、傳遞與交換對顧客、客戶、夥伴及整體社會有價值之提供物的活動、機構與流程。三個值得注意的擴張：

1. **對象擴大**：不只顧客，還包含夥伴與「整體社會」——這是社會行銷觀念被納入定義的痕跡。
2. **從交易到關係**：現代行銷的重心從單次交換移到長期關係（關係行銷、CRM）。
3. **價值是主觀的**：顧客認知價值 ＝ 總認知利益 ÷ 總認知成本。成本不只錢，還有時間、體力、心理成本。這解釋了為什麼便利商店賣的礦泉水比量販店貴還是有人買。

**行銷近視症（Marketing Myopia，Levitt 1960）** 是這章最常被追問的概念：企業用「產品」定義自己的事業，而不是用「顧客需要」。鐵路公司以為自己在做鐵路，其實在做運輸，所以錯過了公路與航空。考題常要你舉例，準備一個。`,
      example: `**全聯**的轉向是常被引用的例子。它早期定位是「便宜」，但便宜是價格層次的競爭，容易被取代。後來的「全聯經濟美學」把訴求改成「懂得省錢是一種生活態度」，把顧客的需要從「省錢」重新定義為「聰明生活」，等於改寫了自己在顧客心中的事業定義。`,
