          explain: '社會行銷觀念要求在顧客欲望、公司利潤與社會長期福祉之間取得平衡。此例中顧客的當下欲望（高糖高鈉的口味）與長期福祉（健康）存在衝突，企業選擇犧牲部分短期毛利以兼顧社會福祉，正是社會行銷觀念的體現。'
