          explain: '環境變化是中性的，必須接上企業自身的資源與能力才會轉化為機會或威脅——高齡化對長照業者與對補習班的意義完全相反。趨勢本身不等於機會，發現得早但沒有對應能力仍然接不住。總體環境無法透過協商改變，這正是它與個體環境的差別。環境掃描也必須是持續性的，因為趨勢會變。'
