          answer: 0,
          explain: 'PESTEL 的價值在於「所以呢」——每一條趨勢都必須推導到對本產業與本企業的具體影響，否則只是一份沒有結論的資料清單。面向數量、量化資料與層次歸類都不是這個情境的主要問題，問題出在分析停在了蒐集階段。'
