            '**推導影響鏈**：趨勢 → 改變了什麼（需求／成本／競爭結構）→ 對業者的具體意義。中間不要跳步。',
            '**指出誰受惠誰受害**：同一趨勢對不同能力的業者影響相反，這句話能顯示你理解「環境是中性的」。',
            '**給一個判斷**：你認為業者現在該做什麼準備。'
