            '指出常見誤用：內外部混淆、列完即止、優勢認定過寬',
            '說明 TOWS 四種配對及其對應的策略姿態，並各舉一例',
            '評論限制：主觀無權重、靜態、優勢認定寬鬆',
            '引入 VRIO 作為優勢的檢驗標準',
            '說明 SWOT 在整體分析流程中的位置'
