      title: '行銷研究流程與研究設計',
      tags: ['必考', '核心'],
      source: 'Malhotra《Marketing Research》；Kotler & Keller',
      brief: `行銷研究是**有系統地蒐集、分析並詮釋資料，以支援行銷決策**。關鍵字是「支援決策」——不能導向決策的研究不值得做。

**五個步驟**：
1. **界定問題與研究目標**（最重要，也最常做錯）
2. **擬定研究計畫**（資料來源、研究方法、抽樣、工具）
3. **蒐集資料**
4. **分析資料**
5. **提出發現與決策建議**

**三種研究設計，對應三種問題**：

| 設計 | 回答什麼 | 典型方法 |
|---|---|---|
| **探索性** | 「到底發生什麼事？」問題還不清楚 | 深度訪談、焦點團體、次級資料 |
| **敘述性** | 「有多少、誰、多常？」 | 問卷調查、觀察 |
| **因果性** | 「A 是不是造成 B？」 | 實驗 |

**只有實驗能證明因果。** 問卷做出來的是相關，不是因果——這句話在面試與申論都極常出現。

**最常見的失敗不在方法，而在第一步**：問題界定錯了，後面做得再精確也沒用。`,
      advanced: `**問題界定的兩種典型錯誤**：
1. **定義過窄**：把「要不要降價」當成研究問題，其實真正的問題是「銷售為什麼下滑」——降價只是其中一個可能解。
2. **定義過寬**：「我們想了解消費者」無法轉成可執行的研究，也無法判斷研究算不算成功。

正確做法是把**管理問題**（要不要推出新包裝？）轉譯成**研究問題**（不同包裝設計對購買意願的影響為何？），再拆成可衡量的假設。這個轉譯能力是行銷研究最核心的功夫。

**因果推論的三個條件**（申論必寫）：
1. **共變**：A 與 B 確實一起變動
2. **時序**：A 發生在 B 之前
3. **排除其他解釋**：沒有第三變數能解釋這個關係

問卷調查通常只能滿足第一項，所以只能談相關。實驗透過**隨機分派**與**控制組**滿足第三項，這是它不可取代的地方。

**實驗設計的效度分兩種**，容易混淆：
- **內部效度**：這個實驗真的證明了 A 導致 B 嗎？（威脅：歷史事件、成熟效應、測驗效應、樣本流失）
- **外部效度**：這個結果能推論到真實市場嗎？（實驗室情境越乾淨，內部效度越高，但外部效度往往越低）

兩者常有取捨關係。**現場實驗**（field experiment）與 **A/B 測試**是折衷方案：在真實情境中做隨機分派，同時保有一定的內部效度。這也是數位行銷相對傳統行銷最大的方法優勢——連回 [[mkt-10-02]] 提到的數位可測量性。

**研究倫理**不可略過：知情同意、匿名與保密、不得偽造資料。台灣的個資法對消費者資料的蒐集、處理與利用有明確規範，未經同意蒐集個資的研究即使結果有效也不可用。`,
      example: `一家餐飲品牌發現來客數下滑，若直接把研究問題訂成「要降價多少才能拉回客人」，等於預設了原因是價格。較妥當的流程是先做**探索性研究**——訪談流失顧客與門市人員，找出可能原因（等候時間、菜色更新慢、停車不便、附近新開競品）；再以**敘述性研究**用問卷確認各原因的普遍程度與影響大小；最後若要驗證「新菜單是否真能提升回購」，才需要**因果性研究**，例如選定條件相近的門市隨機分派試行新菜單並設對照組。

三個階段的順序不能顛倒：跳過探索直接發問卷，問卷上的選項就只會是研究者原本想得到的原因，真正的原因可能從頭到尾都沒被問到。`,
