          answer: 0,
          explain: '高毛利對潛在進入者而言是明確的市場訊號，等於昭告此處有利可圖。因此吸脂訂價需要專利、品牌或通路等進入障礙支撐，否則只是替後進者鋪路。難以回頭漲價與初期虧損是滲透訂價的風險，並非吸脂訂價的問題。'
