          def: '只選擇單一區隔並將資源全數投入的目標市場策略。優點是能建立專家形象、取得該區隔的高市占率並享有作業經濟；主要風險為市場集中，該區隔一旦衰退或被大廠攻入即無退路。',
          tip: '答題時務必補上風險與「多利基」的因應作法，否則只答一半。'
