          answer: 0,
          explain: '健康是該品牌的差異點（POD），但「好喝」是飲料此一品類的類別相似點（POP），屬於進入市場的基本門檻。當 POP 未達標準時，顧客根本不會把該品牌視為合格的選項，差異點再強也無法發揮作用。這正是「POP 是入場券」的意義。'
