          answer: 0,
          explain: '附加產品是超出顧客期望的部分，屬於差異化的主戰場。但一旦競爭者普遍跟進，該屬性便成為顧客理所當然的預期，沉入期望產品層——此時它不再創造加分，缺少反而扣分。這也意味著附加層次的投資必須持續進行。'
