          def: 'EKB 模型提出：需要察覺、資訊搜尋、方案評估、購買決策、購後行為。此為描述高涉入複雜購買的完整流程；低涉入購買可能大幅簡化。',
          tip: '一定要補「不是每次購買都會完整走過」，這句話能一次帶出涉入度的討論。'
