          answer: 0,
          explain: '涉入度是購買情境的特質，受價格、風險（功能／財務／社會／時間）、自我表達與享樂價值等多重因素影響，非由產品類別單獨決定。一雙鞋對球鞋收藏者是高涉入，對只求能走路的顧客則是低涉入。低涉入產品也可透過連結重要議題、加入自我表達或享樂元素而向高涉入方向移動——星巴克把咖啡從商品變成生活方式即為典型。'
