          explain: '信念屬於認知層次的判斷（「我以為 X 是這樣」），資訊到位即可改變。態度則整合了認知、情感與行為傾向三個成分，改變需要持續的正向經驗累積而非單次資訊。因此當行銷目標是改變顧客對品牌的長期態度時，仰賴單次廣告的溝通策略往往效果有限，必須設計持續的顧客體驗方能奏效。'
